/**
 * Conformance vectors vendored from `decimal128-resources/string_bid_dpd`,
 * generated by the decimal128-c engine and shared with the full ports.
 *
 * The four edge-case files are carried here in full -- 2438 rows. They are the
 * ones that discriminate: every defect found while building this codec lived
 * in one of them -- the underscore separators, the bracketed NaN payloads, the
 * non-canonical declets. The fifth file, `canonical`, is 84,764 rows of mostly
 * common-path volume and is not vendored; at these densities it would be some
 * 7 MB of Kotlin source.
 *
 * Transcribed as source rather than carried as data files because
 * `commonTest` has no portable file access, so a data file would need
 * expect/actual readers for every target. As source, every target runs them.
 *
 * Rows are packed as `text|hex|hex` to keep the tables dense. No vector text
 * contains a bar; two error vectors do contain commas, which is why the
 * generator honoured the corpus quoting rather than splitting naively.
 */
class TestCorpusVectors {

    private fun split3(row: String): Triple<String, String, String> {
        val a = row.indexOf('|')
        val b = row.indexOf('|', a + 1)
        return Triple(row.substring(0, a), row.substring(a + 1, b), row.substring(b + 1))
    }

    private fun hi(h: String) = h.substring(0, 16).toULong(16).toLong()
    private fun lo(h: String) = h.substring(16, 32).toULong(16).toLong()
    private fun hex(a: Long, b: Long) =
        a.toULong().toString(16).padStart(16, '0').uppercase() +
        b.toULong().toString(16).padStart(16, '0').uppercase()

