    @Test
    fun parseVectorsProduceBothEncodings() {
        for (row in parseVectors) {
            val (text, bidHex, dpdHex) = split3(row)
            val b = LongArray(2)
            assertNull(Decimal128TextCodec.bid128Parse(b, text), text)
            assertEquals(bidHex, hex(b[0], b[1]), "bid128Parse <" + text + ">")
            val d = LongArray(2)
            assertNull(Decimal128TextCodec.dpd128Parse(d, text), text)
            assertEquals(dpdHex, hex(d[0], d[1]), "dpd128Parse <" + text + ">")
        }
    }

    @Test
    fun errorVectorsAreRejectedByBothFormats() {
        for (row in errorVectors) {
            val bar = row.lastIndexOf('|')
            val text = row.substring(0, bar)
            val why = row.substring(bar + 1)
            val b = LongArray(2)
            val d = LongArray(2)
            val bErr = Decimal128TextCodec.bid128Parse(b, text)
            val dErr = Decimal128TextCodec.dpd128Parse(d, text)
            assertNotNull(bErr, "bid128Parse accepted <" + text + ">, corpus says " + why)
            assertNotNull(dErr, "dpd128Parse accepted <" + text + ">, corpus says " + why)
            assertEquals(bErr, dErr, "the formats disagree on <" + text + ">")
        }
    }

    @Test
    fun nonCanonicalEncodingsRenderCorrectly() {
        for (row in nonCanonicalVectors) {
            val (text, bidHex, dpdHex) = split3(row)
            assertEquals(text, Decimal128TextCodec.bid128ToString(hi(bidHex), lo(bidHex)), "bid #" + bidHex)
            assertEquals(text, Decimal128TextCodec.dpd128ToString(hi(dpdHex), lo(dpdHex)), "dpd #" + dpdHex)
        }
    }

    @Test
    fun sampleRoundTripsInBothFormats() {
        for (row in sampleVectors) {
            val (text, bidHex, dpdHex) = split3(row)
            assertEquals(text, Decimal128TextCodec.bid128ToString(hi(bidHex), lo(bidHex)), "bid #" + bidHex)
            assertEquals(text, Decimal128TextCodec.dpd128ToString(hi(dpdHex), lo(dpdHex)), "dpd #" + dpdHex)
            val b = LongArray(2)
            assertNull(Decimal128TextCodec.bid128Parse(b, text), text)
            assertEquals(bidHex, hex(b[0], b[1]), "bid128Parse <" + text + ">")
            val d = LongArray(2)
            assertNull(Decimal128TextCodec.dpd128Parse(d, text), text)
            assertEquals(dpdHex, hex(d[0], d[1]), "dpd128Parse <" + text + ">")
        }
    }
